


var state={lesson:0,page:'首页',read:0,vocab:0,showPy:true,showFr:true,showEn:true,readingMode:false,say:0,teacher:false,selectedW:null,selectedP:null,progress:JSON.parse(localStorage.getItem('ce2Progress')||'{}')};var pages=['首页','课程库','全册课文','我来读','我来认','我来说','我来写','我来练','我来玩','我来评价'];function $(s){return document.querySelector(s)}function $$(s){return Array.from(document.querySelectorAll(s))}function L(){return lessonData[state.lesson]}function save(){localStorage.setItem('ce2Progress',JSON.stringify(state.progress))}function done(k){state.progress[L().id+'-'+k]=true;save()}function shuffle(a){return a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1])}var featuredCharByLesson={1:['门','开','关','早','午'],3:['中','你','我'],9:['肉'],10:['鱼'],13:['上','下']};


function featuredChars(){return featuredCharByLesson[L().no]||[]}


function isFeaturedChar(ch){return featuredChars().indexOf(ch)>=0}


function highlightFeaturedText(s){var text=esc(s);var chars=featuredChars();chars.forEach(function(ch){var safe=esc(ch);text=text.split(safe).join('<span class="feature-char">'+safe+'</span>')});return text}


function featureBadgeFor(ch){return isFeaturedChar(ch)?'<span class="feature-badge">默写汉字</span>':''}


function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function thumbs(){var x=$('#thumbs');x.classList.add('show');setTimeout(()=>x.classList.remove('show'),900)}function win(){var x=$('#win');x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1800)}function nav(){ $('#nav').innerHTML=pages.map(p=>'<button class="'+(state.page===p?'active':'')+'" data-p="'+p+'">'+p+'</button>').join('');$$('[data-p]').forEach(b=>b.onclick=()=>{state.page=b.dataset.p;render()})}


function render(){nav();$('#topTitle').textContent=L().no+'. '+L().titleZh+' · CE2 · '+(L().themeFr||'Mandarin A1');var A=$('#app'); if(state.page==='首页')A.innerHTML=home(); if(state.page==='课程库')A.innerHTML=library(); if(state.page==='全册课文')A.innerHTML=allTexts(); if(state.page==='我来读')A.innerHTML=read(); if(state.page==='我来认')A.innerHTML=vocab(); if(state.page==='我来说')A.innerHTML=say(); if(state.page==='我来写')A.innerHTML=write(); if(state.page==='我来练')A.innerHTML=practice(); if(state.page==='我来玩')A.innerHTML=play(); if(state.page==='我来评价')A.innerHTML=evalPage(); bind(); bindGameActionButtons();}


function home(){return '<div class="panel hero"><div><div class="fr">CE2 · A1 · IFS · CE2 全册资料版</div><h1 class="h1" onclick="speak(L().titleZh)">'+L().titleZh+'</h1><div class="fr" style="font-size:40px">'+esc(L().themeFr)+'</div><div class="toolbar"><button onclick="state.page=\'我来读\';render()">开始学习</button><button class="light" onclick="state.page=\'课程库\';render()">选择课程</button><button class="red" onclick="speak(L().titleZh)">🔊 点读</button></div><p class="fr">© Ni Zheng 2026 All Rights Reserved.</p></div><img class="cover" src="'+L().image+'" onclick="speak(L().titleZh)"></div>'}








function library(){return '<h2 class="h2">课程库</h2><div class="lesson-grid">'+lessonData.map(function(l,i){return '<button class="lesson-card" onclick="state.lesson='+i+';state.page=\'首页\';state.read=0;state.vocab=0;render()"><img src="'+l.image+'"><h3>'+l.no+'. '+l.titleZh+'</h3><p>'+esc(l.themeFr)+'</p>'+(l.no===14?'<div class="toolbar"><span class="light" style="display:inline-block;padding:10px 14px;border-radius:14px;font-weight:900">进入CE2框架版</span></div>':'')+'</button>'}).join('')+'</div>'}






function applyPinyinReplacements(py){var s=String(py||'');var pairs=[["shén me","shénme"],["yán sè","yánsè"],["zhōng wén","Zhōngwén"],["Zhōng wén","Zhōngwén"],["lǜ sè","lǜsè"],["Lǜ sè","Lǜsè"],["hóng sè","hóngsè"],["Hóng sè","Hóngsè"],["lán sè","lánsè"],["Lán sè","Lánsè"],["huáng sè","huángsè"],["Huáng sè","Huángsè"],["hēi sè","hēisè"],["Hēi sè","Hēisè"],["bái sè","báisè"],["Bái sè","Báisè"],["huī sè","huīsè"],["Huī sè","Huīsè"],["shū bāo","shūbāo"],["lǎo shī","lǎoshī"],["tóng xué","tóngxué"],["xué xiào","xuéxiào"],["jiào shì","jiàoshì"],["tú shū guǎn","túshūguǎn"],["yóu yǒng chí","yóuyǒngchí"],["cāo chǎng","cāochǎng"],["cān tīng","cāntīng"],["cè suǒ","cèsuǒ"],["zhè lǐ","zhèlǐ"],["nà lǐ","nàlǐ"],["běn zi","běnzi"],["qiān bǐ","qiānbǐ"],["chǐ zi","chǐzi"],["xiàng pí","xiàngpí"],["xīng qī","xīngqī"],["jīn tiān","jīntiān"],["shēng rì","shēngrì"],["bà ba","bàba"],["mā ma","māma"],["gē ge","gēge"],["jiě jie","jiějie"],["dì di","dìdi"],["mèi mei","mèimei"],["rèn shi","rènshi"],["gāo xìng","gāoxìng"],["miàn tiáo","miàntiáo"],["mǐ fàn","mǐfàn"],["jī fàn","jīfàn"],["niú ròu","niúròu"],["jī ròu","jīròu"],["chéng zhī","chéngzhī"],["kě lè","kělè"],["biǎo mèi","biǎomèi"],["kè tīng","kètīng"],["wò shì","wòshì"],["chú fáng","chúfáng"],["yù shì","yùshì"],["huā yuán","huāyuán"],["dù zi","dùzi"],["bù shū fu","bù shūfu"],["shēng qì","shēngqì"],["Luò Bīn wáng","Luò Bīnwáng"]];pairs.sort(function(a,b){return b[0].length-a[0].length}).forEach(function(p){s=s.split(p[0]).join(p[1])});return s}


function normalizePinyinPunctuation(s){return String(s||'').replace(/。/g,'.').replace(/？/g,'?').replace(/！/g,'!').replace(/，/g,',').replace(/、/g,',')}


function capitalizePinyinSentences(s){s=String(s||'').trim().replace(/\s+/g,' ');var out='',cap=true;for(var i=0;i<s.length;i++){var ch=s[i];if(cap&&/[A-Za-zÀ-ÿǍǎǏǐǑǒǓǔǕǖǗǘǙǚǛǜĀāĒēĪīŌōŪūÁáÉéÍíÓóÚúǸǹŃńḾḿ]/.test(ch)){ch=ch.toLocaleUpperCase();cap=false}else if(/[.!?]/.test(ch)){cap=true}else if(/\S/.test(ch)){cap=false}out+=ch}return out}


function tidyPinyinText(py){var s=applyPinyinReplacements(py||'');s=normalizePinyinPunctuation(s);return s.replace(/\s+([,.!?])/g,'$1').replace(/([,.!?])(?=\S)/g,'$1 ').replace(/\s+/g,' ').trim()}


var properPinyinMap={'中国人':'Zhōngguó rén','法国人':'Fǎguó rén','西班牙人':'Xībānyá rén','瑞士人':'Ruìshì rén','新加坡人':'Xīnjiāpō rén','中文书':'Zhōngwén shū','花木兰':'Huā Mùlán','丁丁':'Dīngdīng','唐诗':'Táng shī','骆宾王':'Luò Bīnwáng','Lucas':'Lucas','Léa':'Léa','Noé':'Noé','Sofia':'Sofia','Emma':'Emma','Alice':'Alice'};


function lowerPinyinInitial(s){s=tidyPinyinText(s);if(/^T(\s|$)/.test(s))return s;return s.replace(/^([A-ZÀ-ÖØ-Þ])/,function(m){return m.toLocaleLowerCase()})}


function formatPinyinText(py){return capitalizePinyinSentences(tidyPinyinText(py))}


function pinyinForDisplay(zh,py){var exact='';try{exact=pinyinLookup(zh||'')}catch(e){}return esc(formatPinyinText(exact||py||''))}


function pinyinForWordRaw(zh,py){if(properPinyinMap[zh])return properPinyinMap[zh];var exact='';try{exact=pinyinLookup(zh||'')}catch(e){}return lowerPinyinInitial(exact||py||'')}


function pinyinForWordDisplay(zh,py){return esc(pinyinForWordRaw(zh,py))}





function allTexts(){var l=L();return '<h2 class="h2">全册课文浏览</h2><div class="panel"><div class="toolbar"><button onclick="state.lesson=Math.max(0,state.lesson-1);state.read=0;render()">上一课</button><button onclick="state.lesson=Math.min(lessonData.length-1,state.lesson+1);state.read=0;render()">下一课</button><button class="light" onclick="state.page=\'课程库\';render()">返回课程库</button><button class="red" onclick="speak(L().titleZh)">🔊 读课题</button></div><div class="hero" style="grid-template-columns:.9fr 1.1fr"><div><div class="fr">Leçon '+l.no+' · CE2</div><h1 class="h1" onclick="speak(L().titleZh)">'+esc(l.titleZh)+'</h1><div class="fr" style="font-size:34px">'+esc(l.themeFr||'Mandarin A1')+'</div><div class="toolbar"><button onclick="state.page=\'我来读\';render()">进入本课互动阅读</button></div></div><img class="cover" src="'+l.image+'" onclick="speak(L().titleZh)"></div><div style="margin-top:18px">'+l.reading.map((r,i)=>'<div class="card reading-card"><div><span class="avatar">'+readSpeakerName(r)+'</span><span class="zh" onclick="state.read='+i+';speakReadingLine('+i+')">'+esc(r.zh)+'</span></div><div class="py">'+pinyinForDisplay(r.zh,r.py)+'</div><div class="fr">'+esc(r.fr||'')+'</div><div class="en">'+esc(r.en||'')+'</div></div>').join('')+'</div></div>'}function readLinePinyin(r){return pinyinForDisplay(r.zh,r.py)}


function readSpeakerName(r){return esc(r.speaker||r.s||'\u8bfb')}


function readLineEnglish(r){return esc((r.en||'').trim())}





function poemSection(){var poem=L().poem||[]; if(!poem.length) return ''; return '<div class="section-subtitle">古诗《咏鹅》</div><div class="read-grid poem-grid">'+poem.map(function(r,i){return '<div class="read-card poem-card" data-i="poem-'+i+'"><div class="zh" onclick="speak(\''+esc(r.zh)+'\')">'+r.zh+'</div><div class="py">'+pinyinForDisplay(r.zh,r.py)+'</div><div class="fr">'+(r.fr||'')+'</div><div class="en">'+(r.en||'')+'</div></div>';}).join('')+'</div>';}





function read(){var cards=L().reading.map(function(r,i){return '<div class="card reading-card '+(i===state.read?'current':'')+'" style="display:'+(state.readingMode&&i!==state.read?'none':'block')+'"><div><span class="avatar">'+readSpeakerName(r)+'</span><span class="zh read-sentence" data-read-index="'+i+'">'+esc(r.zh)+'</span></div><div class="py read-py" style="display:'+(state.showPy?'block':'none')+'">'+readLinePinyin(r)+'</div><div class="fr read-fr" style="display:'+(state.showFr?'block':'none')+'">'+esc(r.fr||'')+'</div><div class="en read-en" style="display:'+(state.showEn?'block':'none')+'">'+readLineEnglish(r)+'</div></div>'}).join('');return '<h2 class="h2">我来读</h2><div class="panel"><div class="toolbar read-toolbar"><button type="button" data-read-action="toggle-py">'+(state.showPy?'📖 Masquer le pinyin':'📖 Afficher le pinyin')+'</button><button type="button" data-read-action="toggle-fr">'+(state.showFr?'🇫🇷 Hide French':'🇫🇷 Show French')+'</button><button type="button" data-read-action="toggle-en">'+(state.showEn?'🇬🇧 Hide English':'🇬🇧 Show English')+'</button><button type="button" data-read-action="reading-mode">'+(state.readingMode?'All Sentences':'Reading Mode')+'</button><button type="button" data-read-action="full-read">🔊 Read All</button><button type="button" data-read-action="pause-read">Pause</button><button type="button" data-read-action="continue-read">Continue</button><button type="button" data-read-action="previous">Previous</button><button type="button" data-read-action="slow">👄 Slow</button><button type="button" data-read-action="repeat">🔁 Repeat</button><button type="button" data-read-action="next">Next</button></div>'+cards+poemSection()+yongEStudentStudySection()+'</div>'}


function scrollToCurrentReading(){setTimeout(function(){var el=document.querySelector('.reading-card.current');if(el)el.scrollIntoView({behavior:'smooth',block:'center'});},80)}


function continueFullReading(){state.fullReadingPaused=false;speakFullText(Math.min(state.read||0,(L().reading||[]).length-1))}


function bindReadingControls(){var buttons=$$('[data-read-action]');buttons.forEach(function(btn){btn.addEventListener('click',function(ev){ev.preventDefault();var a=btn.getAttribute('data-read-action');if(a==='toggle-py'){state.showPy=!state.showPy;render();return}if(a==='toggle-fr'){state.showFr=!state.showFr;render();return}if(a==='toggle-en'){state.showEn=!state.showEn;render();return}if(a==='reading-mode'){state.readingMode=!state.readingMode;render();return}if(a==='full-read'){speakFullText(state.fullReadingPaused?(state.read||0):0);return}if(a==='pause-read'){stopFullReading();return}if(a==='continue-read'){continueFullReading();return}if(a==='previous'){state.read=Math.max(0,state.read-1);render();return}if(a==='next'){state.read=Math.min(L().reading.length-1,state.read+1);render();return}if(a==='repeat'){stopFullReading();speak((L().reading[state.read]||{}).zh||'');return}if(a==='slow'){stopFullReading();speak((L().reading[state.read]||{}).zh||'','slow');return}})});$$('.read-sentence').forEach(function(el){el.addEventListener('click',function(){state.read=Number(el.getAttribute('data-read-index'))||0;speak((L().reading[state.read]||{}).zh||'');render()})})}


function yongEStudentStudySection(){


  if(L().no!==14)return '';


  var img=L().image;


  var observe=[


    ['曲项','qū xiàng','le cou courbé','弯弯的脖子向着天空。'],


    ['白毛','bái máo','les plumes blanches','白色的羽毛浮在绿色的水面上。'],


    ['红掌','hóng zhǎng','les pattes rouges','红红的脚掌在水里划呀划。']


  ];


  var poem=[


    ['鹅，鹅，鹅，','É, é, é,','Oie, oie, oie,','鹅鹅鹅：好像在叫小朋友们来看呢！'],


    ['曲项向天歌。','Qū xiàng xiàng tiān gē.','Le cou courbé, elle chante vers le ciel.','曲项向天歌：伸长脖子对着天空唱歌。'],


    ['白毛浮绿水，','Bái máo fú lǜ shuǐ,','Ses plumes blanches flottent sur l’eau verte,','白毛浮绿水：白色的羽毛漂在绿色的水面上。'],


    ['红掌拨清波。','Hóng zhǎng bō qīng bō.','Ses pattes rouges remuent l’eau claire.','红掌拨清波：红红的脚掌在水里划呀划。']


  ];


  var actions=[['学大鹅叫','鹅，鹅，鹅'],['仰起小头','向天唱歌'],['张开翅膀','白毛浮水'],['双脚划水','红掌拨波']];


  return '<div class="section-subtitle">古诗学习 · 认识大白鹅</div><div class="panel yong-study" style="margin-top:16px"><div class="hero" style="grid-template-columns:1fr 1fr;align-items:center"><div><h3 class="h2" style="margin-top:0">找一找大白鹅的秘密</h3><p class="fr">Observe l’oie blanche, puis lis le poème avec les gestes.</p><div class="grid three">'+observe.map(function(o){return '<button class="card" onclick="speak(\''+o[0]+'。'+o[3]+'\')"><div class="zh" style="font-size:48px">'+o[0]+'</div><div class="py">'+o[1]+'</div><div class="fr">'+o[2]+'</div><p>'+o[3]+'</p></button>'}).join('')+'</div></div><img class="cover" src="'+img+'" onclick="speak(\'鹅，鹅，鹅，曲项向天歌。\')"></div><div class="card" style="margin-top:16px"><h3>骆宾王的小故事</h3><p class="zh" style="font-size:34px;line-height:1.45" onclick="speak(\'很久很久以前，有个叫骆宾王的小朋友，他只有七岁。\')">很久很久以前，有个叫骆宾王的小朋友，他只有七岁。</p><p class="zh" style="font-size:30px;line-height:1.45" onclick="speak(\'有一天，他在池塘边看到了一群可爱的大白鹅，它们正在水里快乐地游泳。小宾王觉得太美了，于是就写下了这首传诵千年的古诗。\')">有一天，他在池塘边看到了一群可爱的大白鹅，它们正在水里快乐地游泳。小宾王觉得太美了，于是就写下了这首传诵千年的古诗。</p><p class="fr">Il était une fois un enfant nommé Luo Binwang. À sept ans, il a vu de belles oies blanches au bord de l’étang et a composé ce poème.</p></div><div class="section-subtitle">诗句理解 · Comprendre le poème</div><div class="read-grid poem-grid">'+poem.map(function(p){return '<div class="read-card poem-card"><div class="zh" style="font-size:40px" onclick="speak(\''+p[0]+'\')">'+p[0]+'</div><div class="py">'+p[1]+'</div><div class="fr">'+p[2]+'</div><p>'+p[3]+'</p></div>'}).join('')+'</div><div class="section-subtitle">节奏与动作 · Lire avec le corps</div><div class="grid four">'+actions.map(function(a){return '<button class="card" onclick="speak(\''+a[1]+'\')"><div class="zh" style="font-size:36px">'+a[0]+'</div><div class="fr">'+a[1]+'</div></button>'}).join('')+'</div><div class="card" style="margin-top:16px"><h3>课后小任务</h3><p class="zh" style="font-size:32px" onclick="speak(\'请画出你心中的大白鹅。\')">请画出你心中的“大白鹅”，明天带来和大家一起分享吧！</p><p class="fr">Dessine l’oie blanche que tu imagines et apporte ton dessin pour le partager en classe.</p></div></div>';


}





