function vocabIconData(zh){return vocabIconMap[zh]||vocabIconMap[zh.replace(/[？！?！。]/g,'')]||vocabIconMap['中文书']}


function vocabArt(v,no){var zh=(v&&v.zh)||'';var ai=vocabAiImage(zh);if(ai)return ai;var icon=vocabIconData(zh);var safe=esc(zh);var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 300"><rect width="420" height="300" rx="28" fill="#f8fbff"/><circle cx="68" cy="66" r="34" fill="#68b7e8" opacity=".35"/><circle cx="350" cy="230" r="54" fill="#d8202f" opacity=".08"/><rect x="26" y="226" width="368" height="40" rx="20" fill="#082f63" opacity=".08"/><image href="data:image/svg+xml;base64,'+icon+'" x="112" y="54" width="196" height="196"/><text x="210" y="284" text-anchor="middle" font-size="34" font-family="KaiTi, STKaiti, serif" fill="#8b1e24" font-weight="900">'+safe+'</text></svg>';return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)}


function vocabList(){return L().vocab&&L().vocab.length?L().vocab:[{zh:L().titleZh,py:"",fr:"",en:""}]}function speakCurrentVocab(){var list=vocabList();var v=list[((state.vocab||0)+list.length)%list.length];if(v&&v.zh)speak(v.zh)}function selectVocab(i){var list=vocabList();state.vocab=((i||0)+list.length)%list.length;render();setTimeout(speakCurrentVocab,80)}function changeVocab(delta){var list=vocabList();state.vocab=((state.vocab||0)+delta+list.length)%list.length;if(delta>0)done("vocab");render();setTimeout(speakCurrentVocab,80)}


function vocabChipFont(zh){var n=Array.from(String(zh||'')).length;return n>=10?'10px':n>=9?'12px':n>=8?'13px':n>=7?'14px':n>=6?'16px':n>=5?'18px':n>=4?'22px':'30px'}function vocab(){var list=L().vocab&&L().vocab.length?L().vocab:[{zh:L().titleZh,py:'',fr:'',en:''}];state.vocab=((state.vocab||0)+list.length)%list.length;var v=list[state.vocab];var chips=list.map(function(item,i){return '<button class="vocab-chip '+(i===state.vocab?'active':'')+'" style="--chip-zh:'+vocabChipFont(item.zh)+'" onclick="selectVocab('+i+')"><span class="zh">'+esc(item.zh)+'</span><small>'+pinyinForWordDisplay(item.zh,item.py)+'</small></button>'}).join('');return '<h2 class="h2">我来认</h2><div class="panel vocab"><div class="wordbig"><div class="zh" onclick="speak(L().vocab[state.vocab%L().vocab.length].zh)">'+esc(v.zh)+'</div><div class="py">'+pinyinForWordDisplay(v.zh,v.py)+'</div><div class="fr">'+esc(v.fr)+'</div><div class="en">'+esc(v.en||'')+'</div><div class="toolbar"><button type="button" onclick="changeVocab(-1)">Previous</button><button type="button" onclick="changeVocab(1)">Next</button></div><div class="vocab-list">'+chips+'</div></div><div><div class="blur" onclick="this.classList.add(&quot;reveal&quot;);speak(L().vocab[state.vocab%L().vocab.length].zh)"><img class="image-full vocab-art" src="'+vocabArt(v,L().no)+'" alt="'+esc(v.zh)+'"></div><div class="vocab-credit">点击图片点读 / Clique l’image pour écouter</div></div></div>'}





function speakingScene(no,idx){var arr=speakingSceneMap[no]||[];return arr[idx]||arr[0]||L().image}


function say(){


var lesson=L();var patterns=(lesson.speakingPatterns&&lesson.speakingPatterns.length?lesson.speakingPatterns:(lesson.patterns||[]).map(function(x){return typeof x==='string'?{title:x,prompt:x,answer:''}:x;}));


if(!patterns.length){patterns=[{title:'句型练习',prompt:(lesson.reading[0]&&lesson.reading[0].zh)||lesson.titleZh,answer:(lesson.reading[1]&&lesson.reading[1].zh)||''}];}


state.say=((state.say||0)+patterns.length)%patterns.length;var p=patterns[state.say];


var answer=p.answer||((lesson.reading[state.read%lesson.reading.length]||{}).zh)||'';


var prompt=p.prompt||p.title||'';


var sceneSrc=speakingScene(lesson.no,state.say);


return '<h2 class="h2">我来说</h2><div class="panel grid say-section"><div class="c6"><div class="mini">'+esc(p.title||'句型')+'</div><div class="say-card question" data-say-text="'+esc(prompt)+'" data-say-voice="male"><div class="mini">问 / Question</div><div class="zh">'+esc(prompt)+'</div></div><div class="say-card answer" data-say-text="'+esc(answer)+'" data-say-voice="female"><div class="mini">答 / Réponse</div><div class="zh">'+esc(answer||'我来说一说。')+'</div></div><div class="toolbar"><button data-say-action="prev">Previous</button><button data-say-action="listen-q">🔊 问句</button><button data-say-action="listen-a">🔊 答句</button><button data-say-action="auto">Auto Play</button><button data-say-action="practice">🎤 Practice</button><button data-say-action="next">Next</button></div><div class="feedback" id="sayFeedback">选择一个句型，点击句子或图片点读。</div></div><div class="c6"><img class="image-full" src="'+sceneSrc+'" data-say-text="'+esc(prompt+'。'+answer)+'" data-say-voice="female"><div class="toolbar"><button data-say-action="image">🔊 图片</button><button onclick="document.documentElement.requestFullscreen&&document.documentElement.requestFullscreen()">Fullscreen</button></div></div></div>'}


function writingItems(){return (L().writing&&L().writing.length?L().writing:L().chars||[]).slice(0,12)}





