  svg.addEventListener('lostpointercapture',function(e){end(e,true);},opts);
  window.addEventListener('pointerup',function(e){end(e,false);},opts);
  window.addEventListener('pointercancel',function(e){end(e,true);},opts);
  document.addEventListener('visibilitychange',function(){if(document.hidden&&pointer!==null)end({pointerId:pointer},true);},opts);
