function practiceAnswerFrench(g,ans,a){if(!a)return '';var n=L().no, i=g.index||0;if(g&&g.frAnswers&&g.frAnswers[ans]&&normalizeChineseSentence(ans)===normalizeChineseSentence(a))return g.frAnswers[ans];if(n===1&&i===0)return practiceIdx(g,ans)===1?'Je vais tr\u00e8s bien.':'Je vais bien.';if(n===4&&i===1)return 'Oui, j\u2019ai '+practiceVal(g,ans,['un grand fr\u00e8re','une grande s\u0153ur','un petit fr\u00e8re','une petite s\u0153ur'])+'.';if(n===5&&i===0)return 'Oui, ici, c\u2019est '+practiceVal(g,ans,['l\u2019\u00e9cole','la salle de classe','la biblioth\u00e8que','la piscine','le terrain de sport','la cantine','les toilettes'])+'.';if(n===5&&i===1)return 'Oui, l\u00e0-bas, c\u2019est '+practiceVal(g,ans,['la biblioth\u00e8que','la piscine','le terrain de sport','la cantine','les toilettes','l\u2019\u00e9cole','la salle de classe'])+'.';if(n===7&&i===0)return 'Mon '+practiceVal(g,ans,['cartable','cahier','crayon','uniforme scolaire'])+' est bleu.';if(n===8&&i===0)return 'Oui, j\u2019aime manger '+practiceVal(g,ans,['du riz au poulet','des raviolis chinois','des nouilles','du riz'])+'.';if(n===8&&i===1)return 'Oui, j\u2019aime boire '+practiceVal(g,ans,['de l\u2019eau','du th\u00e9','du jus d\u2019orange','du coca'])+'.';if(n===9&&i===0)return 'Oui, je veux manger '+practiceVal(g,ans,['du riz','du b\u0153uf','du poulet','des nouilles'])+'.';if(n===13&&i===0)return practiceVal(g,ans,['Elle est dans la chambre.','Elle est dans le salon.','Elle est dans la cuisine.','Elle est dans le jardin.']);if(n===13&&i===1)return 'Oui, elle est '+practiceVal(g,ans,['dans le salon','dans la chambre','dans la cuisine','dans la salle de bain','dans le jardin'])+'.';if(n===14&&i===0)return practiceVal(g,ans,['C\u2019est une oie.','C\u2019est une oie blanche.','C\u2019est un cygne.']);return practiceFrenchQuestion(g,ans,a)}


