function completeSentencePinyin(g, ans, sentence){var full=sentenceToPinyin(sentence||''); if(full)return formatPinyinText(full); var py=(g.py||'').trim(); var a=pinyinLookup(ans); if(py.indexOf('...')>=0) return py.replace(/\.\.\./g,a||ans); if(py.indexOf('____')>=0) return py.replace(/____/g,a||ans); return formatPinyinText(py || (a?('('+a+')'):''));}


function completeSentenceFrench(g, ans, sentence){if(g&&g.frAnswers&&g.frAnswers[ans])return g.frAnswers[ans];var fr=frenchLookup(ans), s=normalizeChineseSentence(sentence);function safe(x){return /[\u3400-\u9fff]/.test(x||'')?'':x}function cap(x){x=String(x||'');return x?x.charAt(0).toUpperCase()+x.slice(1):x}var family={爸爸:'mon père',妈妈:'ma mère',哥哥:'mon grand frère',姐姐:'ma grande sœur',弟弟:'mon petit frère',妹妹:'ma petite sœur',叔叔:'mon oncle',阿姨:'ma tante'};var haveFamily={哥哥:'un grand frère',姐姐:'une grande sœur',弟弟:'un petit frère',妹妹:'une petite sœur'};var place={学校:'l’école',教室:'la salle de classe',图书馆:'la bibliothèque',游泳池:'la piscine',操场:'le terrain de sport',餐厅:'la cantine',厕所:'les toilettes'};function placeFr(prefix,where){var p=place[ans]||fr;if(ans==='厕所')return prefix.replace('c’est','ce sont')+p+where;return prefix+p+where}var objectPoss={书包:'ton cartable',本子:'ton cahier',铅笔:'ton crayon',校服:'ton uniforme'};fr=safe(fr)||safe(g.fr)||'la bonne réponse'; if(/你好吗/.test(s)) return ans==='我非常好'?'Je vais très bien.':'Je vais bien.'; if(/谢谢|不客气|不用谢/.test(s)) return ans==='谢谢'?'Merci.':'De rien.'; if(/^请/.test(s)) return 'S’il vous plaît, '+fr+'.'; if(/这是我的/.test(s)) return 'C’est '+(family[ans]||fr)+'.'; if(/你有.*吗/.test(s)) return 'As-tu '+(haveFamily[ans]||fr)+' ?'; if(/我有一个/.test(s)) return 'J’ai '+(haveFamily[ans]||fr)+'.'; if(/这里是.*吗/.test(s)) return placeFr('Est-ce que c’est ',' ici ?'); if(/那里是.*吗/.test(s)) return placeFr('Est-ce que c’est ',' là-bas ?'); if(/这里是/.test(s)) return placeFr('Ici, c’est ','.'); if(/那里是/.test(s)) return placeFr('Là-bas, c’est ','.'); if(/我可以借/.test(s)) return 'Puis-je emprunter '+fr+' ?'; if(/给你/.test(s)) return 'Voici '+fr+' pour toi.'; if(/今天是/.test(s)) return 'Aujourd’hui, c’est '+fr+'.'; if(/我的生日是/.test(s)) return 'Mon anniversaire est '+fr+'.'; if(/我叫/.test(s)) return 'Je m’appelle '+fr+'.'; if(/我是/.test(s)) return 'Je suis '+fr+'.'; if(/很高兴认识你|我也很高兴认识你/.test(s)) return cap(fr)+'.'; if(/是什么颜色/.test(s)) return 'De quelle couleur est '+(objectPoss[ans]||fr)+' ?'; if(/我的书包是.*的/.test(s)) return 'Mon cartable est '+fr+'.'; if(/我的校服是.*的/.test(s)) return 'Mon uniforme est '+fr+'.'; if(/您喜欢吃/.test(s)) return 'Aimez-vous manger '+fr+' ?'; if(/喜欢吃/.test(s)) return 'Aimes-tu manger '+fr+' ?'; if(/您喜欢喝/.test(s)) return 'Aimez-vous boire '+fr+' ?'; if(/喜欢喝/.test(s)) return 'Aimes-tu boire '+fr+' ?'; if(/我喜欢/.test(s)) return 'J’aime '+fr+'.'; if(/想吃.*吗/.test(s)) return 'Veux-tu manger '+fr+' ?'; if(/我想喝/.test(s)) return 'Je voudrais boire '+fr+'.'; if(/我们去/.test(s)) return fr==='manger'?'Allons manger !':'Allons à '+fr+' !'; if(/我想要一只/.test(s)) return 'Je voudrais un '+fr+'.'; if(/这只.*很可爱/.test(s)) return 'Ce '+fr+' est très mignon.'; if(/我的.*是白色的/.test(s)) return 'Mon animal est blanc.'; if(/疼/.test(s)) return 'J’ai mal '+fr+'.'; if(/我很/.test(s)) return 'Je suis '+fr+'.'; if(/我不舒服/.test(s)) return 'Je ne me sens pas bien.'; if(/我生气/.test(s)) return 'Je suis fâché(e).'; if(/今天我穿/.test(s)) return 'Aujourd’hui, je porte '+fr+'.'; if(/我穿/.test(s)||/我戴/.test(s)) return 'Je porte '+fr+'.'; if(/她在.*吗/.test(s)) return 'Est-elle dans '+fr+' ?'; if(/她在/.test(s)) return cap(fr)+'.'; if(/那是什么/.test(s)) return 'Qu’est-ce que c’est ?'; if(/那是白鹅/.test(s)) return 'C’est une oie blanche.'; if(/那是天鹅/.test(s)) return 'C’est un cygne.'; if(/那是鹅/.test(s)) return 'C’est une oie.'; if(/骆宾王.*岁/.test(s)) return 'Luo Binwang a '+fr+' ans.'; if(/我们一起读《咏鹅》吧/.test(s)) return 'Lisons « Ode à l’oie » ensemble !'; if(/我们一起读诗吧/.test(s)) return 'Lisons le poème ensemble !'; if(/我们一起读吧/.test(s)) return 'Lisons ensemble !'; if(/一起.*吧/.test(s)) return 'Lisons ensemble !'; return safe(g.fr)||'Phrase complète.';}


function completedSentenceMeta(g, ans, sentence){return {py:completeSentencePinyin(g,ans,sentence), fr:completeSentenceFrench(g,ans,sentence)};}


function fillPracticeBlank(ans){var g=state.practiceGame;if(!g)return;if(g.answers.indexOf(ans)>=0){var pair=practicePairMeta(g,ans);var qEl=$('#practiceQuestion');if(qEl)qEl.textContent=pair.q;var aEl=$('#practiceAnswerLine');if(aEl)aEl.innerHTML=pair.a?'<div class="avatar">答</div><span class="zh" id="practiceAnswerText" onclick="speak(\''+esc(pair.a)+'\')" style="font-size:52px">'+esc(pair.a)+'</span>':'';$('#practiceDrop').textContent='✓ '+ans;var py=$('#practicePy');if(py)py.textContent=pair.py;var fr=$('#practiceFr');if(fr)fr.textContent=pair.fr;$('#msg').textContent='⭐ 太棒了！现在请用新的词语再说一遍问句和答句。';speakPair(pair.q||'',pair.a||'');done('practice')}else{$('#msg').textContent='🔁 再试一次。请注意中文句子的结构。';speak('不对，再试一次')}}


function play(){return '<h2 class="h2">我来玩</h2><div class="panel"><div class="game-sections">'+


'<div class="card game-section"><h3>汉字理解</h3><div class="toolbar game-toolbar"><button type="button" data-game-action="findChar" onclick="runGameAction(&quot;findChar&quot;)">找一找｜Trouve le caractère</button><button type="button" data-game-action="gameMatch" onclick="runGameAction(&quot;gameMatch&quot;)">汉字配对｜Associe les caractères</button></div></div>'+


'<div class="card game-section"><h3>词汇理解</h3><div class="toolbar game-toolbar"><button type="button" data-game-action="wordPairGame" onclick="runGameAction(&quot;wordPairGame&quot;)">词语配对｜Associe les mots</button><button type="button" data-game-action="listenChoose" onclick="runGameAction(&quot;listenChoose&quot;)">听一听，选一选｜Écoute et choisis</button></div></div>'+


'<div class="card game-section"><h3>句型与对话</h3><div class="toolbar game-toolbar"><button type="button" data-game-action="sentenceGame" onclick="runGameAction(&quot;sentenceGame&quot;)">我会说句子｜Construis une phrase</button><button type="button" data-game-action="orderDialogue" onclick="runGameAction(&quot;orderDialogue&quot;)">排一排｜Remets le dialogue dans l’ordre</button></div></div>'+


'<div class="card game-section"><h3>综合理解</h3><div class="toolbar game-toolbar"><button type="button" data-game-action="tfGame" onclick="runGameAction(&quot;tfGame&quot;)">判断对错｜Vrai ou faux</button></div></div>'+


'</div><div id="gameHost" class="fr">请选择一个类别里的小游戏。Les activités sont rangées du caractère vers la phrase.</div></div>'}


function evalPage(){var rows=['Je peux comprendre des mots familiers et des phrases très simples de la leçon.','Je peux reconnaître les mots importants et les associer à une image ou à leur sens.','Je peux poser et répondre à des questions simples avec un camarade, avec de l’aide si besoin.','Je peux copier et écrire les caractères de la leçon en respectant le bon ordre des traits.'];return '<h2 class="h2">我来评价</h2><div class="panel">'+rows.map(function(r,i){return '<div class="card"><span class="fr">'+r+'</span><select data-self="'+i+'" onchange="saveSelfEval(this)">'+['🙂 Je peux','😐 Avec aide','🔁 Je m’entraîne'].map(function(label){return '<option'+(state.progress[L().id+'-self'+i]===label?' selected':'')+'>'+label+'</option>'}).join('')+'</select></div>'}).join('')+'</div>'}


function saveSelfEval(sel){state.progress[L().id+'-self'+sel.dataset.self]=sel.value;save()}




















function bindSayControls(){


$$('.say-card,[data-say-action="image"],.say-section .image-full').forEach(function(el){


 el.onclick=function(){var txt=el.dataset.sayText||L().titleZh;var voice=el.dataset.sayVoice||'female';speak(txt,voice);};


});


$$('[data-say-action]').forEach(function(btn){btn.onclick=function(ev){


 ev.stopPropagation();var patterns=(L().speakingPatterns&&L().speakingPatterns.length?L().speakingPatterns:L().patterns||[]);if(!patterns.length)return;state.say=((state.say||0)+patterns.length)%patterns.length;var p=patterns[state.say];var prompt=p.prompt||p.title||p;var answer=p.answer||'';var fb=$('#sayFeedback');


 if(btn.dataset.sayAction==='prev'){state.say=(state.say+patterns.length-1)%patterns.length;render();return;}


 if(btn.dataset.sayAction==='next'){state.say=(state.say+1)%patterns.length;render();return;}


 if(btn.dataset.sayAction==='listen-q'){speak(prompt,'male');if(fb)fb.textContent='问句：认真听，再跟老师读。';return;}


 if(btn.dataset.sayAction==='listen-a'){speak(answer,'female');if(fb)fb.textContent='答句：声音清楚，语调自然。';return;}


 if(btn.dataset.sayAction==='auto'){speak(prompt,'male');setTimeout(function(){speak(answer,'female');},1400);if(fb)fb.textContent='自动播放：先听问句，再听答句。';return;}


 if(btn.dataset.sayAction==='practice'){if(fb)fb.textContent='AI 鼓励反馈：⭐ 真棒！请注意声调和节奏，再读一次会更自然。';speak('真棒，请再读一次。','female');return;}


 if(btn.dataset.sayAction==='image'){speak(L().titleZh,'female');return;}


};});


}


function bind(){bindReadingControls();bindSayControls(); $$('.drag').forEach(d=>d.ondragstart=e=>e.dataTransfer.setData('text/plain',d.dataset.word));if($('#practiceDrop')){$('#practiceDrop').ondragover=e=>e.preventDefault();$('#practiceDrop').ondrop=e=>{var w=e.dataTransfer.getData('text/plain');fillPracticeBlank(w)}}else if($('#drop')){$('#drop').ondragover=e=>e.preventDefault();$('#drop').ondrop=e=>{var w=e.dataTransfer.getData('text/plain');$('#sentence').textContent=L().patterns[0].zh.replace('____',w);$('#drop').textContent='✓ '+w;speak($('#sentence').textContent);$('#msg').textContent='⭐ 太棒了！ / Très bien! / Excellent!';done('pattern')}}}


function splitWordPairText(zh){var chars=Array.from(String(zh||'').trim()).filter(function(ch){return ch.trim()});if(chars.length<2)return null;return {front:chars[0],back:chars.slice(1).join('')}}


function wordPairItems(){var seen={};var list=(L().vocab||[]).map(function(v){var sp=splitWordPairText(v.zh);if(!sp||seen[v.zh])return null;seen[v.zh]=true;return {zh:v.zh,py:v.py||'',fr:v.fr||'',en:v.en||'',front:sp.front,back:sp.back}}).filter(Boolean);return shuffle(list).slice(0,Math.min(8,Math.max(4,list.length))).map(function(v,i){v.idx=i;return v})}


function wordPairGame(reset){var items=wordPairItems();if(!items.length){$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">词语配对｜Associe les mots</h2><div class="card fr">本课没有足够的双字或多字词语。</div>';return}if(reset||!state.wordPairGame||state.wordPairGame.lesson!==state.lesson){state.wordPairGame={lesson:state.lesson,items:items,left:shuffle(items.slice()),right:shuffle(items.slice()),matchedLeft:[],matchedRight:[],selectedLeft:null,selectedRight:null,lines:[]}}var g=state.wordPairGame;if(!g.matchedLeft)g.matchedLeft=(g.matched||[]).slice();if(!g.matchedRight)g.matchedRight=(g.matched||[]).slice();$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">词语配对｜Associe les mots</h2><p class="fr">左边选词语前面的字，右边选后面的字；只要能组成课内正确词语，就算正确。 / Associe un début et une fin pour former un mot correct de la leçon.</p><div class="word-pair-board" id="wordPairBoard"><svg class="word-pair-lines" id="wordPairLines"></svg><div class="word-pair-col"><h3 class="fr">前面的字 / Début</h3>'+g.left.map(function(v){var done=g.matchedLeft.indexOf(v.idx)>=0;return '<button class="pair-card pair-left '+(g.selectedLeft===v.idx?'active ':'')+(done?'matched':'')+'" data-pair-left="'+v.idx+'" onclick="pickWordPair(&quot;left&quot;,'+v.idx+',this)"><span class="zh">'+esc(v.front)+'</span><small class="fr">'+(done?esc(v.zh):'')+'</small></button>'}).join('')+'</div><div class="word-pair-col"><h3 class="fr">后面的字 / Fin</h3>'+g.right.map(function(v){var done=g.matchedRight.indexOf(v.idx)>=0;return '<button class="pair-card pair-right '+(g.selectedRight===v.idx?'active ':'')+(done?'matched':'')+'" data-pair-right="'+v.idx+'" onclick="pickWordPair(&quot;right&quot;,'+v.idx+',this)"><span class="zh">'+esc(v.back)+'</span><small class="fr">'+(done?esc(v.py||v.fr||''):'')+'</small></button>'}).join('')+'</div></div><div class="toolbar"><button onclick="wordPairGame(true)">再玩一次 / Rejouer</button><span id="score" class="fr">Score: '+g.matchedLeft.length+' / '+g.items.length+'</span></div><div id="msg" class="fr"></div>';setTimeout(drawWordPairLines,60)}


function wordPairByIdx(idx){var g=state.wordPairGame;return (g&&g.items||[]).find(function(x){return x.idx===idx})||{}}


function validWordPair(leftIdx,rightIdx){var g=state.wordPairGame;if(!g)return null;var left=wordPairByIdx(leftIdx),right=wordPairByIdx(rightIdx);var word=(left.front||'')+(right.back||'');var found=(g.items||[]).find(function(x){return x.zh===word});return found||null}


function pickWordPair(side,idx,el){var g=state.wordPairGame;if(!g)return;if(!g.matchedLeft)g.matchedLeft=[];if(!g.matchedRight)g.matchedRight=[];if(side==='left'&&g.matchedLeft.indexOf(idx)>=0)return;if(side==='right'&&g.matchedRight.indexOf(idx)>=0)return;if(side==='left'){g.selectedLeft=idx;speak((wordPairByIdx(idx)||{}).zh||'')}else g.selectedRight=idx;if(g.selectedLeft!=null&&g.selectedRight!=null){var wordObj=validWordPair(g.selectedLeft,g.selectedRight);if(wordObj){var leftIdx=g.selectedLeft,rightIdx=g.selectedRight,left=wordPairByIdx(leftIdx),right=wordPairByIdx(rightIdx);if(g.matchedLeft.indexOf(leftIdx)<0)g.matchedLeft.push(leftIdx);if(g.matchedRight.indexOf(rightIdx)<0)g.matchedRight.push(rightIdx);g.lines.push({left:leftIdx,right:rightIdx});$('#msg').textContent='👍 太棒了！ '+(left.front||'')+' + '+(right.back||'')+' = '+wordObj.zh+' / Très bien !';speak(wordObj.zh||'太棒了');thumbs();g.selectedLeft=null;g.selectedRight=null;if(g.matchedLeft.length===g.items.length){done('game-word-pair');setTimeout(win,350)}wordPairGame(false)}else{var a=document.querySelector('[data-pair-left="'+g.selectedLeft+'"]'),b=document.querySelector('[data-pair-right="'+g.selectedRight+'"]');[a,b].forEach(function(x){if(x){x.classList.remove('wrong');void x.offsetWidth;x.classList.add('wrong')}});$('#msg').textContent='🔁 再试一次！';speak('不对，再试一次');setTimeout(function(){g.selectedLeft=null;g.selectedRight=null;wordPairGame(false)},500)}}else wordPairGame(false)}


function drawWordPairLines(){var g=state.wordPairGame,svg=$('#wordPairLines'),board=$('#wordPairBoard');if(!g||!svg||!board)return;var br=board.getBoundingClientRect();svg.innerHTML='';(g.lines||[]).forEach(function(pair){var leftIdx=typeof pair==='object'?pair.left:pair,rightIdx=typeof pair==='object'?pair.right:pair;var l=document.querySelector('[data-pair-left="'+leftIdx+'"]'),r=document.querySelector('[data-pair-right="'+rightIdx+'"]');if(!l||!r)return;var lr=l.getBoundingClientRect(),rr=r.getBoundingClientRect();var x1=lr.right-br.left,y1=lr.top+lr.height/2-br.top,x2=rr.left-br.left,y2=rr.top+rr.height/2-br.top;var line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2);line.setAttribute('class','pair-line');svg.appendChild(line)})}


window.addEventListener('resize',function(){if(state.page==='我来玩')drawWordPairLines()});function gameTitle(){return '<div class="toolbar"><button onclick="state.lesson=Math.max(0,state.lesson-1);state.vocab=0;state.read=0;render()">上一课</button><button onclick="state.lesson=Math.min(lessonData.length-1,state.lesson+1);state.vocab=0;state.read=0;render()">下一课</button><button class="light" onclick="state.page=\'课程库\';render()">课程库</button><span class="fr" style="font-weight:900;align-self:center">Leçon '+L().no+' · '+esc(L().titleZh)+'</span></div>'}


function listenImageable(v){var zh=(v&&v.zh)||'';if(!zh)return false;if(/[……]|在哪里|什么|多少|几月|几日/.test(zh))return false;return !!aiVocabImageMap[zh]||!/[？?]/.test(zh)}function gameItems(){var items=(L().vocab||[]).filter(function(v){return v&&v.zh&&listenImageable(v)});if(!items.length)items=(L().reading||[]).slice(0,6).map(function(r){return {zh:r.zh.replace(/[，。！？!?]/g,'').slice(0,4),py:'',fr:r.fr||'',char:''}});return items}


function charItems(){var items=(L().chars||[]).filter(c=>c&&c.zh);if(!items.length)items=gameItems().map(v=>({zh:(v.char||v.zh||'').slice(0,1),py:v.py||'',fr:v.fr||''})).filter(c=>c.zh);return items.slice(0,10)}


function gameCardImage(label){return '<div class="pic-card-image"><img src="'+vocabArt({zh:label},L().no)+'"><strong>'+esc(label)+'</strong></div>'}


function gameMatch(){var chars=shuffle(charItems()).slice(0,8);var targets=shuffle(chars.slice());state.gameScore=0;$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">汉字配对｜Associe les caractères</h2><p class="fr">拖动汉字到正确的拼音和意思。 / Associe chaque caractère à son pinyin et à son sens.</p><div class="match"><div class="stack">'+chars.map(c=>'<div class="word-card drag-game" draggable="true" data-char="'+esc(c.zh)+'" onclick="speak(\''+esc(c.zh)+'\')">'+esc(c.zh)+'</div>').join('')+'</div><div class="stack">'+targets.map(c=>'<div class="drop target-card" data-target="'+esc(c.zh)+'"><div class="py">'+pinyinForWordDisplay(c.zh,c.py)+' / <span class="fr inline-fr">'+esc(c.fr||c.word||'')+'</span></div></div>').join('')+'</div></div><div class="toolbar"><button onclick="gameMatch()">Rejouer</button><span id="score" class="fr">Score: 0 / '+chars.length+'</span></div><div id="msg" class="fr"></div>';bindGameDrag()}


function bindGameDrag(){$$('.drag-game').forEach(d=>{d.ondragstart=e=>e.dataTransfer.setData('text/plain',d.dataset.char);d.onclick=()=>{state.dragChoice=d.dataset.char;speak(d.dataset.char)}});$$('.target-card').forEach(z=>{z.ondragover=e=>e.preventDefault();z.ondrop=e=>dropChar(e,z);z.onclick=()=>{if(state.dragChoice)checkCharChoice(state.dragChoice,z)}})}


function dropChar(e,z){var ch=e.dataTransfer.getData('text/plain');checkCharChoice(ch,z)}


function checkCharChoice(ch,z){if(ch===z.dataset.target){z.innerHTML='<div class="zh">'+esc(ch)+'</div><div class="fr">⭐ 太棒了！</div>';z.style.background='#dff5ec';var card=$$('.drag-game').find(x=>x.dataset.char===ch);if(card)card.classList.add('gone');state.gameScore=(state.gameScore||0)+1;$('#score').textContent='Score: '+state.gameScore+' / '+$$('.target-card').length;$('#msg').textContent='⭐ 太棒了！ / Très bien! / Excellent!';thumbs();if(state.gameScore===$$('.target-card').length){win();done('game-character-match')}}else{z.classList.add('shake');$('#msg').textContent='🔁 再试一次！ / Réessaie! / Try again!';speak('不对，再试一次');setTimeout(()=>z.classList.remove('shake'),400)}state.dragChoice=null}


function vocabPictureArt(v,no){var zh=(v&&v.zh)||'';var ai=vocabAiImage(zh);if(ai)return ai;var icon=vocabIconData(zh);var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 300"><rect width="420" height="300" rx="28" fill="#f8fbff"/><circle cx="68" cy="66" r="34" fill="#68b7e8" opacity=".35"/><circle cx="350" cy="230" r="54" fill="#d8202f" opacity=".08"/><rect x="26" y="226" width="368" height="40" rx="20" fill="#082f63" opacity=".08"/><image href="data:image/svg+xml;base64,'+icon+'" x="102" y="42" width="216" height="216"/></svg>';return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)}


function listenChoose(newQuestion){var items=gameItems();if(!items.length)return;if(newQuestion||!state.listenGame){var q=items[Math.floor(Math.random()*items.length)];var wrong=shuffle(items.filter(function(v){return v.zh!==q.zh})).slice(0,2);state.listenGame={q:q,opts:shuffle([q].concat(wrong))}}var q=state.listenGame.q;var opts=state.listenGame.opts;$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">听一听，选一选｜Écoute et choisis</h2><div class="toolbar"><button onclick="speak(\''+esc(q.zh)+'\')">🔊 Écouter</button><button onclick="listenChoose(true)">Question suivante</button><button onclick="state.showPy=!state.showPy;listenChoose(false)">'+(state.showPy?'Masquer le pinyin':'Afficher le pinyin')+'</button></div><div class="card"><div class="zh" onclick="speak(\''+esc(q.zh)+'\')">'+esc(q.zh)+'</div><div class="py" style="display:'+(state.showPy?'block':'none')+'">'+pinyinForWordDisplay(q.zh,q.py)+'</div></div><div class="tiles">'+opts.map(function(v){return '<button class="pic-card" onclick="choosePic(\''+esc(v.zh)+'\',\''+esc(q.zh)+'\')"><img class="image-full vocab-art" src="'+vocabPictureArt(v,L().no)+'" alt="picture option"></button>'}).join('')+'</div><div id="msg" class="fr"></div>';if(newQuestion!==false)speak(q.zh)}


function choosePic(k,a){if(k===a){var found=gameItems().find(function(v){return v.zh===a})||{};$('#msg').innerHTML='⭐ 太棒了！<br><span class="fr">'+esc(found.fr||'')+'</span>';thumbs();done('game-listen-choose')}else{$('#msg').textContent='🔁 再试一次！';speak('不对，再试一次')}}


function cleanSentenceOption(s){s=String(s||'').trim();s=s.replace(/T\s*恤/gi,'__TSHIRT__');s=s.replace(/^[AB][：:]\s*/,'').trim();s=s.replace(/([。？！?!])\s*[A-Za-zÀ-ÿ][\s\S]*$/,'$1');if(/[\u3400-\u9fff]/.test(s))s=s.replace(/\s+[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ '\-?.!()]+$/,'');return s.replace(/__TSHIRT__/g,'T恤').replace(/\s+/g,' ').trim()}


function normalizeChineseSentence(s){s=cleanSentenceOption(s);s=s.replace(/T\s*恤/gi,'T恤');s=s.replace(/（[A-Za-zÀ-ÿ0-9\- ]+）/g,'');s=s.replace(/\([A-Za-zÀ-ÿ0-9\- ]+\)/g,'');s=s.replace(/[A-Za-zÀ-ÿ]+/g,function(x){return /^(Lucas|Emma|Alice|Tintin|Léa|Noé|Sofia|T)$/i.test(x)?x:''}).replace(/[()（）\-]/g,'').replace(/\s+/g,'').trim();if(!/[。？！?!]$/.test(s))s+='。';return s}


function sentenceIsUsable(s){return /[\u3400-\u9fff]/.test(s)&&!/[+＋\/]/.test(s)&&s.indexOf('……')<0&&!/句型|回答/.test(s)&&s.replace(/[。？！?!]/g,'').length>=2}


function expandPatternSentences(p){var out=[];var vals=[p.answer,p.prompt];vals.forEach(function(v){v=normalizeChineseSentence(v);if(sentenceIsUsable(v))out.push({sentence:v,source:p})});var t=String(p.title||'');if(t.indexOf('请 + 动作')>=0){['请举手。','请坐好。','请安静。'].forEach(function(s){out.push({sentence:s,source:p})})}return out}


function blankCandidates(sentence){var avoid=['我','你','他','她','是','的','吗','了','在','有','很','也','请','不'];var vocab=(L().vocab||[]).map(function(v){return String(v.zh||'').replace(/（[A-Za-zÀ-ÿ0-9\- ]+）/g,'').replace(/\([A-Za-zÀ-ÿ0-9\- ]+\)/g,'').replace(/[？?。！!()（）\-]/g,'')}).filter(Boolean);var cands=vocab.filter(function(w){return sentence.indexOf(w)>=0&&avoid.indexOf(w)<0}).sort(function(a,b){var d=b.length-a.length;if(d)return d;return sentence.lastIndexOf(b)-sentence.lastIndexOf(a)});if(cands.length)return cands;var body=sentence.replace(/[，。？！?!]/g,'');if(body.length<=3)return [body];var two=body.slice(-2);if(avoid.indexOf(two)<0)return [two];return []}


function makeSentenceQuestion(item){var s=normalizeChineseSentence(item.sentence);if(!sentenceIsUsable(s))return null;var c=blankCandidates(s)[0];if(!c)return null;return {sentence:s,blank:s.replace(c,'____'),answer:c,source:item.source}}


function uniqClean(arr){var seen={};return (arr||[]).map(function(x){return String(x||'').replace(/[。？！?!]/g,'').trim()}).filter(function(x){if(!x||seen[x])return false;seen[x]=true;return true})}


function lessonText(){return JSON.stringify(L())}


function vocabWords(){return uniqClean((L().vocab||[]).map(function(v){return v.zh}))}


function presentWords(list){var words=vocabWords(), text=lessonText();return uniqClean(list).filter(function(w){return words.indexOf(w)>=0||text.indexOf(w)>=0})}


function ensureChineseEnd(s){s=String(s||'').trim();return /[。？！?!]$/.test(s)?s:s+'。'}


function addSentenceRule(rules,blank,answers,py,fr,row){answers=uniqClean(answers);if(!answers.length)return;rules.push({blank:ensureChineseEnd(blank),answers:answers,py:py||'',fr:fr||'Choisis un mot correct pour compléter la phrase.',frAnswers:(row&&row.frAnswers)||null,make:function(ans){return this.blank.indexOf('____')>=0?ensureChineseEnd(this.blank.replace('____',ans)):ensureChineseEnd(ans)}})}


var sentencePatternData={"1":[{"blank":"你好吗？","answers":["我很好","我非常好"],"py":"Nǐ hǎo ma? / Wǒ hěn hǎo.","fr":"Comment vas-tu ? / Je vais bien."},{"blank":"____。","answers":["谢谢","不客气","不用谢"],"py":"Xiè xie. / Bú kè qi. / Bú yòng xiè.","fr":"Merci. / De rien."},{"blank":"请____。","answers":["举手","坐好","安静","排队","开门","关门","开灯","关灯"],"py":"Qǐng ____.","fr":"S’il vous plaît, ____."}],"2":[{"blank":"今天是____。","answers":["九月十五日","五月八日","一月一日","六月二十一日"],"py":"Jīntiān shì ____.","fr":"Aujourd’hui, c’est ____."},{"blank":"我的生日是____。","answers":["五月八日","九月十五日","一月一日","六月二十一日"],"py":"Wǒ de shēngrì shì ____.","fr":"Mon anniversaire est le ____."},{"blank":"今天是____。","answers":["星期一","星期二","星期三","星期四","星期五","星期六","星期日"],"py":"Jīntiān shì ____.","fr":"Aujourd’hui, c’est ____."}],"3":[{"blank":"我叫____。","answers":["Lucas","Léa","Noé","Sofia","Emma"],"py":"Wǒ jiào ____.","fr":"Je m’appelle ____."},{"blank":"我是____。","answers":["法国人","中国人","西班牙人","瑞士人","新加坡人"],"py":"Wǒ shì ____.","fr":"Je suis ____."},{"blank":"____。","answers":["很高兴认识你","我也很高兴认识你"],"py":"Hěn gāoxìng rènshi nǐ.","fr":"Enchanté(e) de faire ta connaissance."}],"4":[{"blank":"这是我的____。","answers":["爸爸","妈妈","哥哥","姐姐","弟弟","妹妹","叔叔","阿姨"],"py":"Zhè shì wǒ de ____.","fr":"C’est ____."},{"blank":"你有____吗？","answers":["哥哥","姐姐","弟弟","妹妹"],"py":"Nǐ yǒu ____ ma?","fr":"As-tu ____ ?"},{"blank":"我有一个____。","answers":["哥哥","姐姐","弟弟","妹妹"],"py":"Wǒ yǒu yí ge ____.","fr":"J’ai ____."}],"5":[{"blank":"这里是____吗？","answers":["学校","教室","图书馆","游泳池","操场","餐厅","厕所"],"py":"Zhèlǐ shì ____ ma?","fr":"Est-ce ____ ici ?"},{"blank":"那里是____吗？","answers":["图书馆","游泳池","操场","餐厅","厕所","学校","教室"],"py":"Nàlǐ shì ____ ma?","fr":"Est-ce ____ là-bas ?"},{"blank":"这里是____。","answers":["学校","教室","图书馆","游泳池","操场","餐厅","厕所"],"py":"Zhèlǐ shì ____.","fr":"Ici, c’est ____."}],"6":[{"blank":"我可以借____吗？","answers":["一支铅笔","一本中文书","一本本子","一把尺子","一块橡皮"],"py":"Wǒ kěyǐ jiè ____ ma?","fr":"Puis-je emprunter ____ ?"},{"blank":"给你____。","answers":["铅笔","中文书","本子","尺子","橡皮"],"py":"Gěi nǐ ____.","fr":"Voici ____ pour toi."},{"blank":"____。","answers":["谢谢","不客气","不用谢"],"py":"Xiè xie. / Bú kè qi. / Bú yòng xiè.","fr":"Merci. / De rien."}],"7":[{"blank":"你的____是什么颜色的？","answers":["书包","本子","铅笔","校服"],"py":"Nǐ de ____ shì shénme yánsè de?","fr":"De quelle couleur est ____ ?"},{"blank":"我的书包是____的。","answers":["蓝色","红色","黄色","绿色","黑色","白色","灰色"],"py":"Wǒ de shūbāo shì ____ de.","fr":"Mon cartable est ____."},{"blank":"我的校服是____的。","answers":["蓝色","白色","灰色"],"py":"Wǒ de xiàofú shì ____ de.","fr":"Mon uniforme est ____."}],"8":[{"blank":"您喜欢吃____吗？","answers":["鸡饭","饺子","面条","米饭"],"py":"Nín xǐhuan chī ____ ma?","fr":"Aimez-vous manger ____ ?"},{"blank":"您喜欢喝____吗？","answers":["水","茶","橙汁","可乐"],"py":"Nín xǐhuan hē ____ ma?","fr":"Aimez-vous boire ____ ?"},{"blank":"我喜欢____。","answers":["吃鸡饭","吃饺子","吃面条","喝茶","喝水","喝橙汁"],"py":"Wǒ xǐhuan ____.","fr":"J’aime ____."}],"9":[{"blank":"你想吃____吗？","answers":["米饭","牛肉","鸡肉","面条"],"py":"Nǐ xiǎng chī ____ ma?","fr":"Veux-tu manger ____ ?"},{"blank":"我想喝____。","answers":["水","茶","橙汁","可乐","奶茶"],"py":"Wǒ xiǎng hē ____.","fr":"Je voudrais boire ____."},{"blank":"我们去____吧！","answers":["食堂","餐厅","吃饭"],"py":"Wǒmen qù ____ ba!","fr":"Allons ____ !"}],"10":[{"blank":"我想要一只____。","answers":["猫","狗","兔子","小猪"],"py":"Wǒ xiǎng yào yì zhī ____.","fr":"Je voudrais ____."},{"blank":"这只____很可爱。","answers":["猫","狗","兔子","小猪"],"py":"Zhè zhī ____ hěn kěài.","fr":"Ce caractère est très mignon."},{"blank":"我的____是白色的。","answers":["猫","狗","兔子"],"py":"Wǒ de ____ shì báisè de.","fr":"Mon animal est blanc."}],"11":[{"blank":"我的____疼。","answers":["腿","脚","肚子","头"],"py":"Wǒ de ____ téng.","fr":"J’ai mal à ____."},{"blank":"我很____。","answers":["高兴","累"],"py":"Wǒ hěn ____.","fr":"Je suis ____."},{"blank":"我____。","answers":["不舒服","生气"],"py":"Wǒ ____.","fr":"Je ____."}],"12":[{"blank":"我穿____。","answers":["校服","裙子","T恤","外套","丁丁的衣服","花木兰的服装"],"py":"Wǒ chuān ____.","fr":"Je porte ____."},{"blank":"我戴____。","answers":["帽子","Alice 的帽子","丁丁的帽子"],"py":"Wǒ dài ____.","fr":"Je porte ____ sur la tête."},{"blank":"今天我穿____。","answers":["校服","裙子","T恤","外套"],"py":"Jīntiān wǒ chuān ____.","fr":"Aujourd’hui, je porte ____."}],"13":[{"blank":"表妹在哪里？","answers":["她在卧室","她在客厅","她在厨房","她在花园"],"py":"Biǎomèi zài nǎlǐ?","fr":"Où est la cousine ?","frAnswers":{"她在卧室":"Elle est dans la chambre.","她在客厅":"Elle est dans le salon.","她在厨房":"Elle est dans la cuisine.","她在花园":"Elle est dans le jardin."}},{"blank":"她在____吗？","answers":["客厅","卧室","厨房","浴室","花园"],"py":"Tā zài ____ ma?","fr":"Est-elle dans ____ ?","frAnswers":{"客厅":"Est-elle dans le salon ?","卧室":"Est-elle dans la chambre ?","厨房":"Est-elle dans la cuisine ?","浴室":"Est-elle dans la salle de bain ?","花园":"Est-elle dans le jardin ?"}},{"blank":"她在____。","answers":["卧室","客厅","厨房","浴室","花园"],"py":"Tā zài ____.","fr":"Elle est dans ____.","frAnswers":{"卧室":"Elle est dans la chambre.","客厅":"Elle est dans le salon.","厨房":"Elle est dans la cuisine.","浴室":"Elle est dans la salle de bain.","花园":"Elle est dans le jardin."}}],"14":[{"blank":"那是什么？","answers":["那是鹅","那是白鹅","那是天鹅"],"py":"Nà shì shénme?","fr":"Qu’est-ce que c’est ?","frAnswers":{"那是鹅":"C’est une oie.","那是白鹅":"C’est une oie blanche.","那是天鹅":"C’est un cygne."}},{"blank":"骆宾王____岁。","answers":["七"],"py":"Luò Bīnwáng ____ suì.","fr":"Luo Binwang a ____ ans.","frAnswers":{"七":"Luo Binwang a sept ans."}},{"blank":"我们一起____吧！","answers":["读","读诗","读《咏鹅》"],"py":"Wǒmen yìqǐ ____ ba!","fr":"Lisons ____ ensemble !","frAnswers":{"读":"Lisons ensemble !","读诗":"Lisons le poème ensemble !","读《咏鹅》":"Lisons « Ode à l’oie » ensemble !"}}]};


function sentenceBuilderItems(){var rows=sentencePatternData[L().no]||[], rules=[];rows.forEach(function(r){addSentenceRule(rules,r.blank,r.answers,r.py,r.fr,r)});return rules.filter(function(r){return r.blank&&r.answers&&r.answers.length})}


function sentenceGame(newQuestion){var items=sentenceBuilderItems();if(!items.length){$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">我会说句子｜Construis une phrase</h2><div class="card fr">本课没有可生成的填空句。</div>';return}if(newQuestion||!state.sentenceGame){var q=items[Math.floor(Math.random()*items.length)];state.sentenceGame={blank:q.blank,answers:q.answers,opts:shuffle(q.answers.slice()),py:q.py,fr:q.fr,make:q.make}}var g=state.sentenceGame;$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">我会说句子｜Construis une phrase</h2><div class="card"><div class="mini">句型填空 / Construis une phrase</div><div class="zh" id="gameSentence" style="font-size:56px;text-align:center">'+esc(g.blank)+'</div><div id="gameSentencePy" class="py" style="text-align:center;display:'+(state.showPy?'block':'none')+'">'+esc(formatPinyinText(g.py||''))+'</div><div id="gameSentenceFr" class="fr" style="text-align:center;display:'+(state.showFr?'block':'none')+'">'+esc(g.fr||'Choisis une réponse correcte.')+'</div></div><div class="tiles">'+g.opts.map(function(a){return '<button class="word-card sentence-choice" onclick="answerSentenceBlank(\''+esc(a)+'\')">'+esc(a)+'</button>'}).join('')+'</div><div class="toolbar"><button onclick="sentenceGame(true)">Question suivante</button><button onclick="state.showPy=!state.showPy;sentenceGame(false)">📖 显示/隐藏拼音 / Afficher/Masquer le pinyin</button><button onclick="state.showFr=!state.showFr;sentenceGame(false)">🇫🇷 显示/隐藏法语 / Afficher/Masquer le français</button><button onclick="speakSentenceModel()">🔊 朗读句型 / Lire le modèle</button></div><div id="msg" class="fr"></div>'}


function answerSentenceBlank(ans){var g=state.sentenceGame;if(!g)return;if(g.answers.indexOf(ans)>=0){var sentence=g.make?g.make(ans):ensureChineseEnd(g.blank.replace('____',ans));sentence=normalizeChineseSentence(sentence);$('#gameSentence').textContent=sentence;var meta=completedSentenceMeta(g,ans,sentence);var py=$('#gameSentencePy');if(py)py.textContent=meta.py;var fr=$('#gameSentenceFr');if(fr)fr.textContent=meta.fr;$('#msg').textContent='⭐ 太棒了！这个完整句子语法正确。';speak(sentence);thumbs();done('game-sentence-builder')}else{$('#msg').textContent='🔁 再试一次！注意句子的意思和语法。';speak('不对，再试一次')}}


function findChar(){var chars=shuffle(charItems()).slice(0,12);var targetOrder=shuffle(chars.map(function(c){return c.zh}));var gridOrder=shuffle(chars.map(function(c){return c.zh}));state.findGame={targets:targetOrder,grid:gridOrder,done:[],current:null};renderFindCharGame()}


function findTargetObj(zh){return charItems().find(function(c){return c.zh===zh})||{zh:zh,py:'',fr:''}}


function nextFindTarget(){var g=state.findGame;if(!g)return null;var left=g.targets.filter(function(ch){return g.done.indexOf(ch)<0});if(!left.length)return null;if(!g.current||g.done.indexOf(g.current)>=0)g.current=left[0];return findTargetObj(g.current)}


function renderFindTarget(){var t=nextFindTarget();if(!t){$('#findTarget').innerHTML='<div class="zh">你太棒了！</div><div class="fr">Tous les caractères sont trouvés.</div>';$('#msg').textContent='⭐ 全部答对了！';win();done('game-find-character-all');return}var g=state.findGame;$('#findTarget').innerHTML='<div class="fr">Target '+(g.done.length+1)+' / '+g.targets.length+'</div><div class="py">'+pinyinForWordDisplay(t.zh,t.py)+'</div><div class="fr">'+esc(t.fr||t.word||'')+'</div>'}


function renderFindCharGame(){var g=state.findGame;if(!g||!g.targets)return findChar();if(!g.grid)g.grid=shuffle(g.targets.slice());var grid=g.grid.map(findTargetObj);$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">找一找｜Trouve le caractère</h2><div class="card" id="findTarget"></div><div class="tiles">'+grid.map(function(c){return '<button class="char-card '+(g.done.indexOf(c.zh)>=0?'gone':'')+'" data-find-char="'+esc(c.zh)+'" onclick="pickChar(\''+esc(c.zh)+'\',this)"><span class="zh">'+esc(c.zh)+'</span></button>'}).join('')+'</div><div class="toolbar"><button onclick="findChar()">Rejouer</button></div><div id="msg" class="fr"></div>';renderFindTarget()}


function pickChar(c,el){var g=state.findGame;if(!g)return;var target=nextFindTarget();if(!target)return;if(c===target.zh){$('#msg').textContent='⭐ 太棒了！继续找下一个。';speak(c);if(g.done.indexOf(c)<0)g.done.push(c);g.current=null;el.style.transform='scale(.82)';el.style.opacity='0';setTimeout(function(){el.style.display='none';renderFindTarget()},220);thumbs();done('game-find-character')}else{el.classList.remove('shake');void el.offsetWidth;el.classList.add('shake');$('#msg').textContent='🔁 再试一次！';speak('不对，再试一次');setTimeout(function(){el.classList.remove('shake')},450)}}


function orderItems(){var arr=(L().dialogue&&L().dialogue.length?L().dialogue:L().reading||[]).map(function(r,i){return Object.assign({},r,{_idx:i,_role:i%2===0?'问':'答'})});return arr}


function orderCardHtml(r,placed){var role=r._role||'读', cls=role==='问'?'question':'answer';var action=placed?'<button class="red" onclick="removeOrderCard('+r._idx+')">Retirer / 移回左侧</button>':'<button onclick="placeOrderCard('+r._idx+',null)">Ajouter / 放到右侧</button>';return '<div class="card order-card '+cls+'" draggable="true" data-idx="'+r._idx+'" data-zh="'+esc(r.zh)+'"><div class="order-head"><span class="avatar">'+esc(role)+'</span><span class="mini">'+(role==='问'?'Question':'Answer')+'</span><button class="light" onclick="event.stopPropagation();speak(\''+esc(r.zh)+'\')">🔊</button></div><span class="zh" onclick="speak(\''+esc(r.zh)+'\')">'+esc(r.zh)+'</span><div class="py" style="display:'+(state.showPy?'block':'none')+'">'+pinyinForDisplay(r.zh,r.py)+'</div><div class="fr" style="display:'+(state.showFr?'block':'none')+'">'+esc(r.fr||'')+'</div><div class="order-card-actions">'+action+'</div></div>'}


function orderDialogue(reset){var items=orderItems();if(reset||!state.orderGame||state.orderGame.lesson!==state.lesson){state.orderGame={lesson:state.lesson,source:shuffle(items.map(function(x){return x._idx})),placed:[]}}var source=state.orderGame.source.map(function(i){return items[i]}).filter(Boolean), placed=state.orderGame.placed.map(function(i){return items[i]}).filter(Boolean);$('#gameHost').innerHTML=gameTitle()+'<h2 class="h2">排一排｜Remets le dialogue dans l’ordre</h2><div class="order-board"><div class="panel order-panel"><h3 class="fr">左侧句卡 / Cartes de phrases</h3><div class="stack order-source">'+source.map(function(r){return orderCardHtml(r,false)}).join('')+'</div></div><div class="panel order-panel order-target-panel"><h3 class="fr">右侧排序区 / Dialogue ordonné</h3><div id="order" class="stack order-target" data-drop="target">'+(placed.length?placed.map(function(r){return orderCardHtml(r,true)}).join(''):'<div class="drop order-empty">把句子拖到这里 / Glisse les phrases ici</div>')+'</div></div></div><div class="toolbar"><button onclick="checkOrder()">Vérifier</button><button onclick="orderDialogue(true)">Rejouer</button><button onclick="state.showPy=!state.showPy;orderDialogue(false)">📖 显示/隐藏拼音 / Afficher/Masquer le pinyin</button><button onclick="state.showFr=!state.showFr;orderDialogue(false)">🇫🇷 显示/隐藏法语 / Afficher/Masquer le français</button></div><div id="msg" class="fr"></div>';bindOrderDrag()}


function bindOrderDrag(){var cards=$$('.order-card');cards.forEach(function(c){c.ondragstart=function(e){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',c.dataset.idx)};c.ondragend=function(){var t=$('#order');if(t)t.classList.remove('order-drop-active')};c.ondragover=function(e){if(c.closest('#order')){e.preventDefault();e.dataTransfer.dropEffect='move'}};c.ondrop=function(e){e.preventDefault();var idx=Number(e.dataTransfer.getData('text/plain'));placeOrderCard(idx,Number(c.dataset.idx))}});var target=$('#order');if(target){target.ondragenter=function(e){e.preventDefault();target.classList.add('order-drop-active')};target.ondragover=function(e){e.preventDefault();e.dataTransfer.dropEffect='move'};target.ondragleave=function(e){if(!target.contains(e.relatedTarget))target.classList.remove('order-drop-active')};target.ondrop=function(e){e.preventDefault();target.classList.remove('order-drop-active');var idx=Number(e.dataTransfer.getData('text/plain'));placeOrderCard(idx,null)}}}


function placeOrderCard(idx,beforeIdx){if(!state.orderGame||isNaN(idx))return;var p=state.orderGame.placed.filter(function(x){return x!==idx});if(beforeIdx===null||isNaN(beforeIdx))p.push(idx);else{var at=p.indexOf(beforeIdx);if(at<0)p.push(idx);else p.splice(at,0,idx)}state.orderGame.placed=p;orderDialogue(false)}


function removeOrderCard(idx){if(!state.orderGame)return;state.orderGame.placed=state.orderGame.placed.filter(function(x){return x!==idx});orderDialogue(false)}


function checkOrder(){if(!state.orderGame)return;var total=orderItems().length, got=state.orderGame.placed.join('|'), ok=state.orderGame.placed.length===total&&got===orderItems().map(function(r){return r._idx}).join('|');$('#msg').textContent=ok?'⭐ 太棒了！问答顺序很清楚。 / Très bien! / Excellent!':'🔁 再试一次！请检查问句和答句是否一组一组对应。';if(ok){thumbs();done('game-dialogue-order')}}


var tf=0,tfScore=0,tfQuestions=[];


