1:[['请开门','请开门。'],['请关门','请关门。'],['请开灯','请开灯。'],['请关灯','请关灯。'],['请举手','请举手。'],['请坐好','请坐好。']],


2:[['星期一','今天是星期一。'],['星期二','今天是星期二。'],['星期三','今天是星期三。'],['星期四','今天是星期四。'],['星期五','今天是星期五。'],['星期六','今天是星期六。'],['星期日','今天是星期日。'],['生日','今天是我的生日。']],


